const item = $input.first().json;
const body = item.body || item;
const m = body.message || {};
// Vapi posts many event types to the same URL; we only log the final report.
if (m.type !== 'end-of-call-report') { return []; }
const a = m.analysis || {};
const call = m.call || {};
// Fields can arrive as classic structuredData or as Vapi Structured Outputs
const f = Object.assign({}, a.structuredData || {});
const so = (m.artifact && m.artifact.structuredOutputs) || {};
for (const o of Object.values(so)) {
  if (!o) continue;
  const r = o.result;
  if (r && typeof r === 'object' && !Array.isArray(r)) { Object.assign(f, r); }
  else if (o.name) { f[o.name] = r; }
}
return [{ json: {
  timestamp: m.startedAt || call.startedAt || new Date().toISOString(),
  caller_name: f.caller_name || 'Unknown',
  phone: f.phone || (m.customer && m.customer.number) || 'Unknown',
  summary: f.summary || a.summary || m.summary || 'No summary available',
  sentiment: f.sentiment || 'neutral',
  outcome: f.outcome || 'info_only'
} }];
